// render-cursor-gitignore.mjs: derives cursor/.gitignore from the full set
// of paths the cursor/ tree is expected to carry: every generated file this
// exporter plans plus every hand-authored path the port map names, mirroring
// the real file's ignore-all-then-allowlist shape (cursor-shapes-study
// section 6 ruling: .gitignore becomes GENERATED, derived here, rather than
// hand-authored). `*` blocks everything by default; one `!` line then
// un-ignores each expected path. Git will not recurse into a directory `*`
// still ignores, so a nested file's own `!` line is not enough on its own;
// this also emits one `!` line per ancestor directory. The .gitignore's own
// path, and the manifest's, are folded into the same allowlist so both
// always keep themselves tracked, exactly like the real file's
// `!/.gitignore` and `!/.claude-port.json` lines.
import { MANIFEST_PATH } from "./exporter-core.mjs";

const GITIGNORE_PATH = ".gitignore";

// HEADER_LINES: matches render-codex-gitignore.mjs's header shape (review
// I-3, "one concrete consequence" item): names the builder, the port map a
// hand_authored entry belongs in, and the exact regeneration command,
// rather than the older two-line header that named neither. Every other
// generated file in cursor/ already carries a GENERATED-header naming the
// builder and the --write command (renderGeneratedHeaderFor); .gitignore
// is the one generated file whose whole purpose used to be hand-editing,
// so it is also the one file whose header a human most needs to read
// before reaching for an editor instead of the regenerator.
const HEADER_LINES = [
  "# GENERATED by translate/cursor.mjs from the planned cursor/ tree. Do not edit;",
  "# add or remove a claude/ source, or a hand_authored entry in",
  "# translate/cursor-port-map.json, then run: node translate/cursor.mjs --write",
  "#",
  "# An allowlist, not a denylist: everything under cursor/ is ignored, then every",
  "# generated and hand-authored file is named back in, so a generated file can no",
  "# longer go missing from git for want of a hand edit. A file a tool drops here",
  "# on its own stays untracked, but the next --write treats it as an orphan and",
  "# DELETES it unless translate/cursor-port-map.json classifies its path (or its",
  "# directory, with a trailing slash) runtime-only-ignored; keep undeclared",
  "# scratch outside cursor/.",
];

// ancestorDirsOf(filePath) -> every ancestor directory of filePath, each
// with a trailing "/", root-relative: "agents/audit-sample.md" ->
// ["agents/"]; "skills/gof/SKILL.md" -> ["skills/", "skills/gof/"]. A
// top-level file (no "/" in its path) has none.
function ancestorDirsOf(filePath) {
  const segments = filePath.split("/");
  const dirs = [];
  for (let depth = 1; depth < segments.length; depth++) dirs.push(`${segments.slice(0, depth).join("/")}/`);
  return dirs;
}

// buildAllowlist(paths) -> every path plus every one of its ancestor
// directories, deduplicated. A Set, not an array: the same directory is
// named by every file inside it, and this collapses those repeats to one
// entry before sorting.
function buildAllowlist(paths) {
  const allowlist = new Set();
  for (const filePath of paths) {
    for (const dir of ancestorDirsOf(filePath)) allowlist.add(dir);
    allowlist.add(filePath);
  }
  return allowlist;
}

// renderCursorGitignore(plannedFiles, handAuthoredPaths) -> { path:
// ".gitignore", content }: plannedFiles is every other file this exporter
// plans (rules, agents, commands, skills, hooks.json, PORT-STATUS.md; the
// manifest and this file itself are not among them yet when this runs, so
// their paths are seeded explicitly). Sorted as plain strings, not
// locale-aware: when one path is a prefix of another (a directory and a
// file inside it), the shorter one always sorts first, which is exactly
// what places a directory's own `!/dir/` line immediately before the `!`
// lines for the files inside it, matching the real file's shape.
export function renderCursorGitignore(plannedFiles, handAuthoredPaths) {
  const seedPaths = [
    GITIGNORE_PATH,
    MANIFEST_PATH,
    ...plannedFiles.map((file) => file.path),
    ...handAuthoredPaths,
  ];
  const lines = [...buildAllowlist(seedPaths)].sort().map((entry) => `!/${entry}`);
  const content = `${[...HEADER_LINES, "*", ...lines].join("\n")}\n`;
  return { path: GITIGNORE_PATH, content };
}
